// ---- generated by scripts/rater_ui/gen_collector.py; do not edit by hand ----
// CONTAINS THE SCREENING ANSWER KEY. This repository must not be made public while recruitment is open: the screening answer key is in preregistration/items/*.json and in the generated collector. Publish after the listening study closes, together with the results.
const GOLD = {
 "scr12": "1",
 "scr10": "1",
 "scrc00": "1",
 "scr06": "1",
 "scr07": "2",
 "scrc04": "1",
 "scr00": "1",
 "scrc11": "2",
 "scrc01": "2",
 "scrc02": "1",
 "scrc10": "1",
 "scrc08": "1",
 "scrc13": "2",
 "scr01": "2",
 "scrc03": "2",
 "scrc09": "2",
 "scr05": "2",
 "scr14": "1",
 "scr03": "2",
 "scr13": "2"
};
const THRESHOLD = 18;   // items that must be correct

export async function onRequestPost({ request, env }) {
  try {
    const d = await request.json();
    const rater = String((d && d.rater) || "");
    // The FIRST attempt is binding. Without this a candidate can retake the gate, flipping answers
    // until they pass -- twenty near-binary items fall to brute force quickly. Later attempts are
    // recorded and answered with the stored verdict, so a retake changes nothing.
    const prior = await env.RATER.get(`gate:${rater}`, "json");
    if (prior) {
      await env.RATER.put(`retake:${rater}:${Date.now()}`, JSON.stringify({ rater, at: Date.now() }));
      const out = { pass: prior.pass, correct: prior.correct, n: prior.n, first_attempt: false };
      if (rater.startsWith("DRY")) out.wrong = prior.wrong;
      return new Response(JSON.stringify(out), { headers: { "content-type": "application/json" } });
    }
    const answers = (d && d.answers) || {};
    const wrong = [];
    let correct = 0, n = 0;
    for (const id in GOLD) {
      n++;
      if (answers[id] === GOLD[id]) correct++; else wrong.push(id);
    }
    const pass = correct >= THRESHOLD;
    const rec = { rater, correct, n, pass, wrong, answers, at: Date.now() };
    await env.RATER.put(`gate:${rater}`, JSON.stringify(rec));
    await env.RATER.put(`screen:${rater}:${Date.now()}`, JSON.stringify(rec));
    const out = { pass, correct, n, first_attempt: true };
    // Returning the missed ids to a real candidate would let them converge by retaking the gate.
    if (rater.startsWith("DRY")) out.wrong = wrong;
    return new Response(JSON.stringify(out), { headers: { "content-type": "application/json" } });
  } catch (e) {
    return new Response(JSON.stringify({ error: String(e) }), { status: 500 });
  }
}
